<?php
declare(strict_types=1);
namespace App\Repositories;
use PDO;
use RuntimeException;
final class AcademicTrajectoryRepository {
 public function __construct(private PDO $db){}
 public function cohorts():array{return $this->db->query("SELECT * FROM cohortes ORDER BY activo DESC,fecha_inicio DESC,id DESC")->fetchAll();}
 public function saveCohort(array $d):int{if($d['id']){$s=$this->db->prepare("UPDATE cohortes SET codigo=:c,nombre=:n,fecha_inicio=:i,fecha_fin_estimada=:f,activo=:a WHERE id=:id");$s->execute(['c'=>$d['codigo'],'n'=>$d['nombre'],'i'=>$d['inicio']?:null,'f'=>$d['fin']?:null,'a'=>$d['activo'],'id'=>$d['id']]);return $d['id'];}$s=$this->db->prepare("INSERT INTO cohortes(codigo,nombre,fecha_inicio,fecha_fin_estimada,activo) VALUES(:c,:n,:i,:f,:a)");$s->execute(['c'=>$d['codigo'],'n'=>$d['nombre'],'i'=>$d['inicio']?:null,'f'=>$d['fin']?:null,'a'=>$d['activo']]);return(int)$this->db->lastInsertId();}
 public function subjectTypes():array{return $this->db->query("SELECT id,codigo,nombre FROM tipos_asignatura WHERE activo=1 ORDER BY nombre")->fetchAll();}
 public function levels():array{return $this->db->query("SELECT id,codigo,nombre,orden_nivel FROM niveles_academicos WHERE activo=1 ORDER BY orden_nivel")->fetchAll();}
 public function subjects():array{return $this->db->query("SELECT a.*,t.nombre tipo,(SELECT COUNT(*) FROM malla_asignaturas ma WHERE ma.asignatura_id=a.id AND ma.activa=1) mallas FROM asignaturas a JOIN tipos_asignatura t ON t.id=a.tipo_asignatura_id WHERE a.deleted_at IS NULL ORDER BY a.activo DESC,a.nombre")->fetchAll();}
 public function saveSubject(array $d):int{if($d['id']){$s=$this->db->prepare("UPDATE asignaturas SET tipo_asignatura_id=:t,codigo=:c,nombre=:n,descripcion=:d,activo=:a WHERE id=:id AND deleted_at IS NULL");$s->execute(['t'=>$d['tipo'],'c'=>$d['codigo'],'n'=>$d['nombre'],'d'=>$d['descripcion']?:null,'a'=>$d['activo'],'id'=>$d['id']]);return$d['id'];}$s=$this->db->prepare("INSERT INTO asignaturas(tipo_asignatura_id,codigo,nombre,descripcion,activo) VALUES(:t,:c,:n,:d,:a)");$s->execute(['t'=>$d['tipo'],'c'=>$d['codigo'],'n'=>$d['nombre'],'d'=>$d['descripcion']?:null,'a'=>$d['activo']]);return(int)$this->db->lastInsertId();}
 public function curricula():array{return $this->db->query("SELECT m.id,m.carrera_id,m.codigo,m.nombre,m.version,c.nombre carrera,e.permite_nuevos_estudiantes FROM mallas_curriculares m JOIN carreras c ON c.id=m.carrera_id JOIN estados_malla e ON e.id=m.estado_malla_id WHERE m.activo=1 AND m.deleted_at IS NULL ORDER BY c.nombre,m.fecha_inicio_vigencia DESC")->fetchAll();}
 public function curriculumSubjects(int $malla):array{$s=$this->db->prepare("SELECT ma.*,a.codigo,a.nombre,n.nombre nivel,n.orden_nivel,(SELECT GROUP_CONCAT(CONCAT(pa.codigo,' · ',pa.nombre) ORDER BY pn.orden_nivel,pa.nombre SEPARATOR ' | ') FROM malla_asignatura_prerrequisitos pr JOIN malla_asignaturas pma ON pma.id=pr.prerrequisito_malla_asignatura_id JOIN asignaturas pa ON pa.id=pma.asignatura_id JOIN niveles_academicos pn ON pn.id=pma.nivel_academico_id WHERE pr.malla_asignatura_id=ma.id AND pr.activo=1) prerrequisitos FROM malla_asignaturas ma JOIN asignaturas a ON a.id=ma.asignatura_id JOIN niveles_academicos n ON n.id=ma.nivel_academico_id WHERE ma.malla_id=:m AND ma.activa=1 ORDER BY n.orden_nivel,ma.orden_en_nivel,a.nombre");$s->execute(['m'=>$malla]);return$s->fetchAll();}
 public function addCurriculumSubject(array $d):int{$s=$this->db->prepare("INSERT INTO malla_asignaturas(malla_id,asignatura_id,nivel_academico_id,creditos,ih_semanal,ih_total,orden_en_nivel,obligatoria,evaluable,activa) VALUES(:m,:a,:n,:c,:s,:t,:o,:ob,:ev,1)");$s->execute(['m'=>$d['malla'],'a'=>$d['asignatura'],'n'=>$d['nivel'],'c'=>$d['creditos'],'s'=>$d['semanal']?:null,'t'=>$d['total']?:null,'o'=>$d['orden']?:null,'ob'=>$d['obligatoria'],'ev'=>$d['evaluable']]);return(int)$this->db->lastInsertId();}
 public function addPrerequisite(int $target,int $req):void{if($target===$req)throw new RuntimeException('Una asignatura no puede ser prerrequisito de sí misma.');$q=$this->db->prepare("SELECT COUNT(*) FROM malla_asignaturas a JOIN malla_asignaturas b ON b.id=:b WHERE a.id=:a AND a.malla_id=b.malla_id");$q->execute(['a'=>$target,'b'=>$req]);if(!(int)$q->fetchColumn())throw new RuntimeException('Los prerrequisitos deben pertenecer a la misma malla.');$s=$this->db->prepare("INSERT INTO malla_asignatura_prerrequisitos(malla_asignatura_id,prerrequisito_malla_asignatura_id,activo) VALUES(:a,:b,1) ON DUPLICATE KEY UPDATE activo=1");$s->execute(['a'=>$target,'b'=>$req]);}
 public function trajectoryStates():array{return $this->db->query("SELECT * FROM estados_trayectoria_academica WHERE activo=1 ORDER BY id")->fetchAll();}
 public function admissionContext(int $student):?array{$s=$this->db->prepare("SELECT sac.carrera_id,sac.sede_id,sac.modalidad_academica_id,sa.tipo_ingreso_id,sa.numero_solicitud,c.nombre carrera,se.nombre sede,mo.nombre modalidad FROM conversiones_admision_estudiante cv JOIN solicitudes_admision sa ON sa.id=cv.solicitud_admision_id LEFT JOIN solicitud_admision_carreras sac ON sac.solicitud_admision_id=sa.id AND sac.seleccionada=1 LEFT JOIN carreras c ON c.id=sac.carrera_id LEFT JOIN sedes se ON se.id=sac.sede_id LEFT JOIN modalidades_academicas mo ON mo.id=sac.modalidad_academica_id WHERE cv.estudiante_id=:e LIMIT 1");$s->execute(['e'=>$student]);return$s->fetch()?:null;}
 public function availableCurricula(int $career, ?int $sedeId=null):array{
  $sql="SELECT DISTINCT m.id,m.codigo,m.nombre,m.version,m.fecha_inicio_vigencia
        FROM mallas_curriculares m
        JOIN estados_malla e ON e.id=m.estado_malla_id
        WHERE m.carrera_id=:c
          AND m.activo=1 AND m.deleted_at IS NULL
          AND e.permite_nuevos_estudiantes=1
          AND m.fecha_inicio_vigencia<=CURDATE()
          AND (m.fecha_fin_vigencia IS NULL OR m.fecha_fin_vigencia>=CURDATE())";
  $params=['c'=>$career];
  if($sedeId!==null && $sedeId>0){
    $sql.=" AND (
      NOT EXISTS(SELECT 1 FROM malla_sedes ms0 WHERE ms0.malla_id=m.id AND ms0.activo=1)
      OR EXISTS(SELECT 1 FROM malla_sedes ms WHERE ms.malla_id=m.id AND ms.sede_id=:sede AND ms.activo=1)
    )";
    $params['sede']=$sedeId;
  }
  $sql.=" ORDER BY m.fecha_inicio_vigencia DESC,m.id DESC";
  $s=$this->db->prepare($sql);$s->execute($params);return $s->fetchAll();
}
 public function trajectories(int $student):array{$s=$this->db->prepare("SELECT ec.*,c.nombre carrera,m.nombre malla,m.codigo malla_codigo,co.nombre cohorte,et.nombre estado,se.nombre sede,mo.nombre modalidad,n.nombre nivel FROM estudiante_carreras ec JOIN carreras c ON c.id=ec.carrera_id JOIN mallas_curriculares m ON m.id=ec.malla_id LEFT JOIN cohortes co ON co.id=ec.cohorte_id JOIN estados_trayectoria_academica et ON et.id=ec.estado_trayectoria_id LEFT JOIN sedes se ON se.id=ec.sede_id LEFT JOIN modalidades_academicas mo ON mo.id=ec.modalidad_academica_id LEFT JOIN niveles_academicos n ON n.id=ec.nivel_referencial_id WHERE ec.estudiante_id=:e AND ec.deleted_at IS NULL ORDER BY ec.fecha_inicio DESC,ec.id DESC");$s->execute(['e'=>$student]);return$s->fetchAll();}
 public function trajectoryHistory(int $trajectory):array{$s=$this->db->prepare("SELECT h.*,ea.nombre anterior,en.nombre nuevo,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) actor FROM historial_estado_trayectoria h LEFT JOIN estados_trayectoria_academica ea ON ea.id=h.estado_anterior_id JOIN estados_trayectoria_academica en ON en.id=h.estado_nuevo_id LEFT JOIN usuarios u ON u.id=h.cambiado_por_usuario_id LEFT JOIN personas p ON p.id=u.persona_id WHERE h.estudiante_carrera_id=:id ORDER BY h.changed_at DESC,h.id DESC");$s->execute(['id'=>$trajectory]);return$s->fetchAll();}
 public function createTrajectory(array $d,int $actor):int{$this->db->beginTransaction();try{$m=$this->db->prepare("SELECT carrera_id FROM mallas_curriculares WHERE id=:m AND activo=1 AND deleted_at IS NULL");$m->execute(['m'=>$d['malla']]);if((int)$m->fetchColumn()!==$d['carrera'])throw new RuntimeException('La malla seleccionada no pertenece a la carrera.');$s=$this->db->prepare("INSERT INTO estudiante_carreras(estudiante_id,carrera_id,malla_id,cohorte_id,estado_trayectoria_id,tipo_ingreso_id,sede_id,modalidad_academica_id,fecha_inicio,nivel_referencial_id,activo) VALUES(:e,:c,:m,:co,:es,:ti,:s,:mo,:f,:n,1)");$s->execute(['e'=>$d['student'],'c'=>$d['carrera'],'m'=>$d['malla'],'co'=>$d['cohorte']?:null,'es'=>$d['estado'],'ti'=>$d['tipo_ingreso']?:null,'s'=>$d['sede']?:null,'mo'=>$d['modalidad']?:null,'f'=>$d['fecha'],'n'=>$d['nivel']?:null]);$id=(int)$this->db->lastInsertId();$h=$this->db->prepare("INSERT INTO historial_estado_trayectoria(estudiante_carrera_id,estado_anterior_id,estado_nuevo_id,motivo,cambiado_por_usuario_id) VALUES(:id,NULL,:es,'Trayectoria académica creada desde Orion',:u)");$h->execute(['id'=>$id,'es'=>$d['estado'],'u'=>$actor]);$this->db->commit();return$id;}catch(\Throwable $e){$this->db->rollBack();throw$e;}}
}
